-- Queer Atlas: verified Greece, Hungary, Slovakia and Croatia events, batch 7.
-- Bulgaria, Romania and Serbia are omitted pending a future queer-led event with verified venue and date.

begin;
alter table if exists public.events add column if not exists event_intel jsonb not null default '{}'::jsonb;
alter table if exists public.events add column if not exists ticket_url text;

with src as (
 select * from jsonb_to_recordset($qa_ghsc_batch7$
[
{"name":"Power Dance Adonis Athens","aliases":["Powerdance Club x Adonis Athens 2026"],"city":"athens","date":"2026-10-03","start_date":"2026-10-03","end_date":"2026-10-04","description":"Powerdance brings its queer Athenian heat to PLEX with London’s Adonis: groovy house, sexy techno and a high-voltage fiesta that knows a good floor is both party and provocation.","link":"https://ra.co/events/gr/athens?startDate=2026-10-03","ticket_url":"https://ra.co/events/gr/athens?startDate=2026-10-03","location":"PLEX, Keramikou 28, 104 36 Athens, Greece","lat":37.9814,"lng":23.7209,"vibe":"queer house and sexy-techno fiesta with Athens/London club energy","intel":{"hours":"23:00 Saturday 3 October 2026; confirm closing time on the active ticket page.","entry_wait":"RA ticketing is live; come early for the best chance of a relaxed entry before a small queer-fiesta floor reaches peak density.","best_arrival":"Arrive at 23:00 for the full house-to-techno arc and easier access to the bar and floor.","crowd_mix":"Athenian queer dancers, Adonis regulars, house lovers and friends drawn to openly sexy, playful club culture.","dress_code":"No fixed code is listed; expressive, dance-ready styling fits a queer fiesta better than formal nightlife polish.","host_inclusivity":"The RA listing explicitly calls it a queer fiesta, joining two queer nightlife communities rather than merely using an inclusive venue.","lineup":"Fancy Shews, K.atou, Maria Politi and Stathis (GR).","age_limit":"Confirm on ticketing.","source_urls":["https://ra.co/events/gr/athens?startDate=2026-10-03","https://soundcheck.club/athens/club/plex/"],"research_status":"ra_listing_and_venue_address_verified","updated_at":"2026-09-26T00:00:00Z"}},
{"name":"EELF × HER Present: Athens","aliases":["EELF x HER Athens Target Demographic Jacopo Sb VRGN"],"city":"athens","date":"2026-10-10","start_date":"2026-10-10","end_date":"2026-10-11","description":"EELF’s first Athens stop meets HER Collective’s queer-feminist local force: two floors of deep groove, forward house and techno that leave room for dancing and for people who too often get pushed to the edge of the room.","link":"https://ra.co/events/2510435","ticket_url":"https://ra.co/events/2510435","location":"IT Athens, Solomou 30 and Mpotasi 9, 10682 Athens, Greece","lat":37.9894,"lng":23.7316,"vibe":"two-floor queer-feminist house and techno with deep grooves and community-led local support","intel":{"hours":"22:00 Saturday 10 October–06:00 Sunday 11 October 2026.","entry_wait":"€10–20 tickets are listed; buy early for the first Athens edition of an international tour.","best_arrival":"Reach IT Athens around 22:00 to move through both rooms before the late-night compression.","crowd_mix":"HER’s queer-feminist community, local electronic-music dancers and EELF’s international house network meet on equal footing.","dress_code":"No formal code is published; practical clubwear and unapologetic self-expression suit the two-stage format.","host_inclusivity":"HER Collective is described as a queer-feminist social collective making inclusive nightlife, queer parties and community gatherings in Athens.","lineup":"Target Demographic, Jacopo Sb, VRGN, pink.wav and FOFI.","age_limit":"18+.","source_urls":["https://ra.co/events/2510435"],"research_status":"ticketing_listing_and_collective_context_verified","updated_at":"2026-09-26T00:00:00Z"}},
{"name":"POPSHE","aliases":["POPSHE Budapest October 2026"],"city":"budapest","date":"2026-10-02","start_date":"2026-10-02","end_date":"2026-10-03","description":"POPSHE gives Budapest a queer-pop release valve: natural wine, drag, all-night dancing and the exact kind of soft-but-loud room where the chorus belongs to everyone.","link":"https://events.musicofourdesire.com/event/ga0j-popshe-party-budapest-hungary","ticket_url":"https://events.musicofourdesire.com/event/ga0j-popshe-party-budapest-hungary","location":"Sárkány, Széll Kálmán tér 5, Budapest, Hungary","lat":47.5070,"lng":19.0248,"vibe":"queer-inclusive pop party with drag, natural wine and all-night dance-floor joy","intel":{"hours":"Friday 2 October 2026; confirm exact doors and closing time via the live organiser ticket page.","entry_wait":"Use the current ticket route and arrive near doors rather than treating the intimate pop party as a guaranteed late walk-up.","best_arrival":"Come early for the social warm-up and stay long enough for the party’s drag-pop crescendo.","crowd_mix":"Queer people, friends and allies seeking a pop-first LGBTQ+ room rather than a generic commercial club.","dress_code":"No published restriction; glitter, a favourite pop-star reference or simply what makes you feel good all make sense.","host_inclusivity":"POPSHE is described as a queer-pop experience and Budapest’s queer-event guides identify it as queer-inclusive with drag.","lineup":"Drag and DJ programme confirmed by organiser.","age_limit":"Confirm on ticketing.","source_urls":["https://events.musicofourdesire.com/event/ga0j-popshe-party-budapest-hungary","https://www.patroc.com/gay/budapest/"],"research_status":"event_listing_and_queer_guide_verified","updated_at":"2026-09-26T00:00:00Z"}},
{"name":"Hello: Queer Pop Party","aliases":["Hello Queer Pop Party Toldi October 2026"],"city":"budapest","date":"2026-10-24","start_date":"2026-10-24","end_date":"2026-10-25","description":"HELLO turns Toldi into a midnight sugar rush for pop divas, QueeRebel dreamers and every over-dressed person who knows a chorus can be a survival skill.","link":"https://ra.co/events/2523657","ticket_url":"https://ra.co/events/2523657","location":"Toldi Klub, Bajcsy-Zsilinszky út 36–38, 1054 Budapest, Hungary","lat":47.5037,"lng":19.0546,"vibe":"colour-saturated queer pop night for divas, dreamers and committed singalong dancers","intel":{"hours":"23:00 Saturday 24 October–05:00 Sunday 25 October 2026.","entry_wait":"The venue reserves the right to refuse entry; arrive early with ID and a clear read of the space rather than assuming a ticket overrides the door.","best_arrival":"Use 23:00 doors to meet the room before the pop anthems pull everyone toward the centre.","crowd_mix":"Queer pop fans, QueeRebel ambassadors, friends and Budapest night owls who want colour rather than cool detachment.","dress_code":"No mandated outfit; the organiser calls for colour and pumped-up style icons.","host_inclusivity":"The event is explicitly branded a queer pop party, with the venue’s door process used to maintain the night’s atmosphere.","lineup":"Gango.","age_limit":"18+.","source_urls":["https://ra.co/events/2523657"],"research_status":"ticketing_listing_verified","updated_at":"2026-09-26T00:00:00Z"}},
{"name":"ZORA 001 × Subdeck mini","aliases":["ZORA 001 Bratislava 2026"],"city":"bratislava","date":"2026-10-02","start_date":"2026-10-02","end_date":"2026-10-03","description":"ZORA starts in the small room with a big corrective: groove-led techno, good music and a floor actively shaped so women and queer people get to occupy space instead of becoming the exception.","link":"https://www.citylife.sk/party/subdeck-mini","ticket_url":"https://www.citylife.sk/party/subdeck-mini","location":"Subdeck, Bratislava, Slovakia","lat":48.1486,"lng":17.1077,"vibe":"low-cap groove techno prioritising women’s and queer people’s freedom of expression","intel":{"hours":"23:00 Friday 2 October 2026; confirm closing time in the current ticket flow.","entry_wait":"Presale is €7–10. The low-cap format makes early purchase and early arrival meaningful.","best_arrival":"Arrive for 23:00 doors to settle into the small room before entry may be regulated to preserve balance.","crowd_mix":"Women and queer people are centred, with men welcome when they support the intended balanced floor.","dress_code":"No formal code; comfortable, expressive dancewear works best in a compact groove-focused room.","host_inclusivity":"ZORA explicitly says it may regulate entry to stop women and queer people becoming a minority by default.","lineup":"Kriya, Laura Plis and Ardjet.","age_limit":"Confirm with organiser.","source_urls":["https://www.citylife.sk/party/subdeck-mini"],"research_status":"official_city_calendar_and_door_principle_verified","updated_at":"2026-09-26T00:00:00Z"}},
{"name":"Queer Pop & Edits Night","aliases":["Zagreb Queer Pop Edits Night 2026"],"city":"zagreb","date":"2026-10-17","start_date":"2026-10-17","end_date":"2026-10-18","description":"Zagreb Theme Party turns Aquarius into a queer-edit universe: heated fandom, pop nostalgia and the pleasure of recognising yourself in a room singing the wrong lyrics at the right volume.","link":"https://core-event.co/en/events/queer-pop-edits-night-ef39/","ticket_url":"https://core-event.co/en/events/queer-pop-edits-night-ef39/","location":"Aquarius, Zagreb, Croatia","lat":45.7903,"lng":15.9522,"vibe":"queer pop and fandom-edit night with 2020s bangers, nostalgia and big communal choruses","intel":{"hours":"21:00 Saturday 17 October–03:00 Sunday 18 October 2026.","entry_wait":"Online tickets only; there is no door sale, and the event will not add a second date if it sells out.","best_arrival":"Come for 21:00 to catch the full edit journey, not only the late singalong peak.","crowd_mix":"Queer fandom communities, pop dancers and people eager for an alternative night out built around shared references.","dress_code":"No rule is stated; a favourite fictional character or pop-era reference fits without being compulsory.","host_inclusivity":"The organiser positions the event as a community gathering around queer characters, series, films and a more welcoming kind of nightlife.","lineup":"DJ programme of pop and queer edits spanning Heartstopper, Skam, Euphoria, Young Royals and more.","age_limit":"18+.","source_urls":["https://core-event.co/en/events/queer-pop-edits-night-ef39/"],"research_status":"official_ticketing_listing_verified","updated_at":"2026-09-26T00:00:00Z"}}
]
$qa_ghsc_batch7$) e(name text,aliases jsonb,city text,date date,start_date date,end_date date,description text,link text,ticket_url text,location text,lat double precision,lng double precision,vibe text,intel jsonb)
), matched as (
 select s.*,x.id existing_id from src s left join lateral(select e.id from public.events e where lower(trim(e.city))=lower(trim(s.city)) and (lower(regexp_replace(trim(e.name),'[^a-z0-9]+','','gi'))=lower(regexp_replace(trim(s.name),'[^a-z0-9]+','','gi')) or exists(select 1 from jsonb_array_elements_text(s.aliases) a where lower(regexp_replace(trim(e.name),'[^a-z0-9]+','','gi'))=lower(regexp_replace(trim(a),'[^a-z0-9]+','','gi'))) or (e.start_date=s.start_date and lower(nullif(trim(e.link),'')) in(lower(s.link),lower(s.ticket_url)))) limit 1)x on true
), updated as (
 update public.events e set name=s.name,description=s.description,link=s.link,ticket_url=s.ticket_url,date=s.date,start_date=s.start_date,end_date=s.end_date,location=s.location,lat=s.lat,lng=s.lng,vibe=s.vibe,vibe_tags=array[]::text[],event_intel=s.intel,seo_indexable=true,seo_quality_status='approved',updated_at=timezone('utc',now()) from matched s where e.id=s.existing_id returning e.id
)
insert into public.events(name,city,description,link,ticket_url,date,start_date,end_date,location,lat,lng,vibe,vibe_tags,event_intel,seo_indexable,seo_quality_status,updated_at)
select name,city,description,link,ticket_url,date,start_date,end_date,location,lat,lng,vibe,array[]::text[],intel,true,'approved',timezone('utc',now()) from matched where existing_id is null;

do $qa_ghsc_batch7_guard$
begin
 if exists(select 1 from public.events where event_intel->>'updated_at'='2026-09-26T00:00:00Z' and (coalesce(trim(description),'')='' or coalesce(trim(location),'')='' or jsonb_array_length(coalesce(event_intel->'source_urls','[]'::jsonb))=0)) then raise exception 'Greece Hungary Slovakia Croatia batch missing editorial data'; end if;
end;
$qa_ghsc_batch7_guard$;
commit;
